add_filter( 'woocommerce_checkout_fields', 'perfectpixel_order_notes_under_billing', 9999 );
add_filter( 'woocommerce_enable_order_notes_field', '__return_false' );

function perfectpixel_order_notes_under_billing( $fields ) {
	if ( isset( $fields['order']['order_comments'] ) ) {
		$notes             = $fields['order']['order_comments'];
		$notes['priority'] = 999;
		$notes['class']    = array( 'form-row-wide' );

		$fields['billing']['order_comments'] = $notes;
		unset( $fields['order']['order_comments'] );
	}
	return $fields;
}
